"""Cierra solamente la validación registrada de F3c; conserva entrega y autores."""
from pathlib import Path
import importlib.util,json,sys
R=Path(__file__).resolve().parents[1]
s=importlib.util.spec_from_file_location('full_F3c_close',R/'herramientas/validar_F3c_completo.py');f=importlib.util.module_from_spec(s);s.loader.exec_module(f)
w=f.w;read=f.read;sha=f.sha;OUT=f.OUT

def main():
    f.guard();assert read(OUT/'verification.json')['checks']['all_passed'];assert not (OUT/'closed.json').exists()
    result=read(OUT/'results.json');controls=read(OUT/'target_controls.json');stress=read(OUT/'fixed_price_stresses.json');sources=read(OUT/'verification.json')['source_models']
    compnames=list(result['gates']);counts=controls['analytical_counts'];primary=counts['primary_kopt']+counts['primary_balance'];archive=R/'privado/corte_F3c_full_final';archive.mkdir(exist_ok=True)
    note='# F3c completo: reproducción, evaluación temporal y límites para el privado\n\n'
    note+=f'Codex, {f.utc()}. Receta registrada antes de nuevos ajustes y evaluador sellado antes de aprender o puntuar en destino. Se conserva el CSV F3c ya enviado y todas las alternativas. Esta unidad no produce ni envía otro archivo del concurso.\n\n'
    note+='## Qué se comprobó\n\nEl reentrenamiento integral de producción ya existente reproduce los 209.063 precios de F3c con el mismo SHA; se cotejó ese recibo y el archivo, sin volver a entrenar producción. La evaluación temporal nueva conserva ambas familias A1, sin F1 y con F1, cada una con las tres semillas fijas 11/12/13, la neutralización F1 por ramo, T2b con C1, la mezcla 50/50 y las capas F2, formas, niveles y factores propios. No se eligió una semilla o un ramo por el resultado.\n\n'
    note+='Se entrenó la fuente con 2021–2023 y todas las calibraciones nuevas con 2023; se aplicaron precios fijos a 59.202 períodos de 2024. El aprendizaje de niveles usa los grupos/folds guardados. El OOF 2023 es material de entrenamiento, con curva compartida y tronco fuente común; no constituye una validación interna completamente anidada. Se reutilizaron curvas y T2b por sus hashes y controles previos.\n\n'
    note+='## Resultados temporales\n\nLas dos primeras vistas mantienen o retiran el bloque propio dentro de la misma estructura pública histórica. Las otras dos retiran global, formas NB y niveles públicos, y aprenden el nivel final por celda en 2023. Esta segunda vista sigue heredando decisiones históricas de variables e hiperparámetros y la forma A_M1 usada para aprender los factores.\n\n'
    note+='| Población 2024 | F3c estructura pública | Misma estructura sin bloque propio | Nivel final 2023, con bloque | Nivel final 2023, sin bloque |\n|---|---:|---:|---:|---:|\n'
    for segment in ['global','new_business','renewal']+f.LINES:
        m=result['metrics'][segment];note+='| '+segment+' | '+' | '.join(f'{m["D2"][name]:.6f}' for name in ['public_full','public_noown','trainlevel_full','trainlevel_noown'])+' |\n'
    note+='\nD² Tweedie 1,5 sobre incurrido neto observado T0. Son resultados locales de 2024 adaptativo; no equivalen al score privado ni permiten predecir su posición.\n\n'
    note+='| Comparación registrada | Δ global | Banda condicional familia 18 | Δ nuevo negocio | Peor piso de estrés | Criterios completos |\n|---|---:|---|---:|---:|---|\n'
    for comp in compnames:
        g=result['metrics']['global'];lo,hi=g['family18'][comp]
        note+=f'| {comp} | {g["deltas"][comp]:+.6f} | [{lo:+.6f}, {hi:+.6f}] | {result["metrics"]["new_business"]["deltas"][comp]:+.6f} | {stress["worst_broad_delta"][comp]:+.6f} | {result["all_gates_pass"][comp]} |\n'
    note+='\nLas bandas usan los mismos 10.000 sorteos por 36.408 componentes cliente/dirección. Familia 18 cubre los contrastes declarados en esta secuencia, no toda la búsqueda adaptativa histórica. Los cinco cortes guardados de 2024 son particiones de un único período temporal, no cinco entrenamientos temporales independientes.\n\n'
    for comp,checks in result['gates'].items():note+='Fallos '+comp+': '+(', '.join(k for k,v in checks.items() if not v) or 'ninguno dentro de los criterios condicionados')+'. La diferencia tras retirar los 37 grupos más favorables es '+f'{result["influence"][comp]["delta_after_removal"]:+.6f}'+'.\n\n'
    note+=f'La cola permanece completa: los {result["tail"]["positive_top_rows"]} períodos del 1% superior entre los positivos concentran {result["tail"]["T0_cost_share"]:.2%} de T0. No se eliminaron ni limitaron sus importes. Los 50 escenarios son sensibilidades de etiquetas con precios fijos; no aportan probabilidades ni demuestran suficiencia de reservas o IBNR.\n\n'
    note+='## Diferencias necesarias y límites\n\nEl CSV 2025 exacto y este análogo temporal no son el mismo archivo ni el mismo horizonte de aprendizaje. Producción aprendió con 2023/2024 y fuente hasta 2024; para evaluar 2024 se corta todo aprendizaje nuevo antes de ese año. Las razones locales de F2, formas y factores se aprenden solo en la vista T2b OOF 2023, en lugar del promedio histórico de vistas 2023/2024. El contraste conserva arquitectura y configuración; no certifica retrospectivamente el archivo entregado como un holdout limpio.\n\n'
    note+='La neutralización F1 se hace sobre tasas anuales, como en el protocolo para el análogo de producción. El diagnóstico histórico de A1 de 2024 neutralizaba costos observados; queda identificada esa diferencia, sin seleccionar el puente por score. La observación posterior de la mezcla usa q de T2b, como m017. A1 conserva exposición redondeada a cuatro decimales para sus offsets; T2b usa exposición calendario.\n\n'
    note+='Los multiplicadores globales, por celda y las formas NB proceden de resultados públicos históricos. Aunque se fijen antes de esta evaluación, siguen condicionados por esa historia. Los antecedentes F1 respetan reporte anterior al inicio, pero la aceptación se observa en el corte posterior disponible. Los maestros no tienen todas las versiones temporales y T0 es una valoración posterior. No se reconstruye con ello la información que realmente habría existido al cotizar.\n\n'
    note+='La receta histórica también depende del lote cotizado: normaliza F1 por ramo y factores/formas por celda dentro de la cartera de aplicación. En la comprobación del bloque posterior, aplicar a la mitad de filas cambia la predicción relativa máxima en '+', '.join(n+' '+f'{z["max_relative"]:.2%}' for n,z in controls['postprocessing_batch_dependence'].items())+'. Esa comprobación mantiene fijo el tronco; no cuantifica además toda la dependencia de neutralización F1. La consistencia punto a punto exige una decisión futura explícita, no un cambio silencioso de esta receta.\n\n'
    note+='## Decisión y siguiente paso\n\nF3c sigue siendo la referencia enviada y conservada; R1 y NB-CRED300 conservan su condición de alternativas. No se cambia la selección manual de Kaggle, no se promueve una receta por esta evaluación adaptativa y no se gasta otro envío. Antes de sustituir el archivo hacen falta una mejora que soporte los pisos por negocio y ramo, control de concentración, evaluación de la sensibilidad de reservas/tiempos y una producción que corresponda exactamente a la receta admitida. Los resultados adversos no se corrigen escogiendo después otro K, subconjunto o mezcla.\n\n'
    note+='## Evidencia y coste\n\n'
    note+=f'Hay 30 ajustes nativos A1 primarios y 30 replays con costos 2024 alterados; 12 ajustes históricos N0/semilla11 se reutilizan por argumentos, modelo y raw idénticos. Cuatro ajustes sintéticos quedan separados. No hay ajustes T2b ni curvas C0 nuevos. Se cuentan {primary} constantes analíticas primarias (kopt y balance), con replays adversos, control positivo y ejemplos sintéticos separados.\n\n'
    note+='Los controles verifican la igualdad de argumentos, modelo, iteraciones y raw bajo alteración real de 2024; el flujo completo destino vuelve a aprender desde el cargador alterado y da los mismos parámetros/precios. Cambiar el entrenamiento sí cambia el resultado. Hay replay exacto sin ajuste desde parámetros guardados, matemáticas escalares por otra implementación, métrica sklearn y 20 sorteos contrastados directamente. Esto es verificación propia de IA, sin aprobación humana inventada ni revisión profesional independiente.\n\n'
    for path in [f.PLAN,OUT/'evaluator_sealed.json',OUT/'parameters.json',OUT/'target_controls.json',OUT/'results.json',OUT/'verification.json']:note+='- '+w.rel(path)+'; SHA '+sha(path)+'\n'
    f.DOC.write_text(note,encoding='utf8')
    forum=f.post(note,'COD-S2-20261028-F3C-COMPLETO-RESULTADOS','F3c completo: resultados temporales, condicionamiento público y decisión privada')
    receipt={'author':'Codex','utc':f.utc(),'status':'F3c_full_structure_validation_completed_exploratory','execution':None,'plan':w.rel(f.PLAN),'plan_sha256':sha(f.PLAN),'output':w.rel(OUT),'report':w.rel(f.DOC),'report_sha256':sha(f.DOC),
        'results':w.rel(OUT/'results.json'),'results_sha256':sha(OUT/'results.json'),'verification':w.rel(OUT/'verification.json'),'verification_sha256':sha(OUT/'verification.json'),'forum':forum,
        'new_native_fits':60,'primary_native_fits':30,'adverse_source_replay_fits_separate':30,'synthetic_native_fits_separate':4,'new_C0_fits':0,'primary_analytical_constants':primary,'analytical_counts_separate':counts,'new_submissions':0,'preserved_reference':'F3c','formal_promotion':False,'private_superiority_not_established':True,'2024_open_adaptive':True,
        'gates':result['all_gates_pass'],'next_unit':'Address documented adverse mechanisms/support and batch dependence under a new registered recipe; do not select or submit by adaptive2024/public alone.'}
    w.update(f.INDEX,receipt,archive);w.update(R/'registro/semana2_mision017_fase2_actual.json',{'utc':f.utc(),'current_batch':receipt,'next_unit':receipt['next_unit']},archive)
    w.update(R/'registro/semana2_mision_privada_actual.json',{'utc':f.utc(),'latest_F3c_full_structure_validation':receipt,'next_unit':receipt['next_unit']},archive)
    state=f.ROOT/'Preparación/ESTADO_PROYECTO.json';w.update(state,{'week_2_mission017_phase2_20261025':receipt},archive)
    summary='\n\n## Validación de F3c con el tronco completo, 27 de octubre de 2026 (Bogotá)\n\nCodex, '+f.utc()+'. Registro y evaluación temporal de la estructura completa N0/F1, tres semillas, T2b/C1, mezcla y todas las capas. CSV entregado preservado y cero envíos. Reproducción integral histórica byteexact reutilizada; nueva evaluación 2023→2024 adaptativo. Control del flujo y verificador pasaron. Resultados y límites: '+w.rel(f.DOC)+'. Estado de criterios condicionados: '+json.dumps(result['all_gates_pass'])+'. No se establece superioridad privada ni se sustituye F3c. La aceptación histórica, maestros sin versiones, valoración de reservas, bloques aprendidos del público y normalización por lote siguen siendo límites materiales.\n'
    for name in ['MEMORIA_PROYECTO.md','DECISIONES.md']:w.append(f.ROOT/'Preparación'/name,summary,archive)
    counter=R/'registro/semana2_contadores_propios_actual.json';c=read(counter);assert 'F3c_full_structure_20261027' not in c
    w.update(counter,{'as_of_utc':f.utc(),'cumulative_price_base_fits':c['cumulative_price_base_fits']+60,'cumulative_closed_form_constants':c['cumulative_closed_form_constants']+primary,'F3c_full_structure_20261027':receipt},archive)
    routes=f.ROOT/'RUTAS_PROYECTO.json';w.update(routes,{'week_2_F3c_full_structure_validation_index':w.rel(f.INDEX),'week_2_F3c_full_structure_validation_report':w.rel(f.DOC)},archive)
    dump(OUT/'closed.json',receipt);print(json.dumps(receipt),flush=True)

if __name__=='__main__':sys.stdout.reconfigure(encoding='utf8');main()
